#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> ones;
    for (int i = 1; i <= N; i++) {
        int x;
        cin >> x;
        if (x == 1) ones.push_back(i);
    }

    long long ans = 0;
    int M = (int)ones.size();

    for (int i = 0; i < M; i++) {
        int p = ones[i];
        int prev = (i == 0 ? 0 : ones[i - 1]);
        int nxt = (i == M - 1 ? N + 1 : ones[i + 1]);

        ans += 1LL * (p - prev) * (nxt - p);
    }

    cout << ans << '\n';
    return 0;
}
